            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            for y, x in stack:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(stack) >= 4:
                components.append((color, stack))

    out = [[bg] * w for _ in range(h)]
    for color, cells in components:
        for r, c in cells:
            out[r][c] = color

    # Restore anomalous cells lying inside the bounds of a large colored patch.
    for r in range(h):
        for c in range(w):
            if out[r][c] != bg:
                continue
            candidates = []
            for color, cells in components:
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                if min(rs) <= r <= max(rs) and min(cs) <= c <= max(cs):
                    candidates.append((color, cells))
            if candidates:
                color, cells = min(
                    candidates,
                    key=lambda item: min(abs(r-y) + abs(c-x) for y, x in item[1])
                )
                out[r][c] = color
    return out
